const bank=[];function q(m,t,p,a,c,e,memo,law='',diff=1){bank.push({id:'q'+bank.length,m,t,p,a,c,e,memo,law,diff})}
q('Comptabilité','notion','Une dette probable, dont le montant ou l’échéance est incertain, relève de…',['Une provision','Une réserve'],0,'Une provision figure dans les capitaux étrangers. Une réserve appartient aux capitaux propres.','PROvision : un PROblème à couvrir.','CO 960e');
q('Comptabilité','notion','Un apport des actionnaires au-delà de la valeur nominale alimente…',['La réserve légale issue du bénéfice','La réserve légale issue du capital'],1,'L’agio provient d’un apport des actionnaires, pas du résultat réalisé.','Capital = ce que les propriétaires apportent.','CO 671');
q('Comptabilité','notion','Une charge de décembre sera payée en janvier. Au bouclement, tu constates…',['Un actif de régularisation','Un passif de régularisation'],1,'La charge appartient à décembre et la dette reste à payer.','Passif : paiement à venir.');
q('Comptabilité','notion','Un loyer payé en décembre concerne janvier prochain. Il faut constater…',['Un actif de régularisation','Un passif de régularisation'],0,'Le paiement anticipe une charge de l’exercice suivant.','Actif : avantage à venir.');
q('Comptabilité','notion','L’amortissement diminue directement le compte de l’immobilisation. Il est…',['Direct','Indirect'],0,'En méthode directe, on crédite le compte de l’actif. En méthode indirecte, on utilise un compte correcteur.','Direct : droit sur l’actif.');
q('Comptabilité','notion','La valeur comptable d’un actif est inférieure à la valeur maximale admissible. Cela peut créer…',['Une réserve latente','Un produit à recevoir'],0,'La sous-évaluation d’un actif peut constituer une réserve latente.','Latente = cachée dans l’évaluation.','',2);
q('Comptabilité','notion','Dans une plage d’activité donnée, le loyer reste identique malgré plus de production. C’est un coût…',['Fixe','Variable'],0,'Le coût fixe ne varie pas avec le volume dans la plage considérée.','Fixe : le volume bouge, lui reste.');
q('Comptabilité','notion','La matière utilisée exclusivement pour un produit est un coût…',['Direct','Indirect'],0,'Un coût direct peut être attribué sans clé de répartition à l’objet de coût.','Direct = destination identifiable.');
q('Comptabilité','notion','Pour une filiale contrôlée, quelle méthode reprend les actifs et passifs poste par poste ?',['L’intégration globale','La mise en équivalence'],0,'L’intégration globale reprend les postes de la filiale ; les parts de tiers sont présentées séparément.','Globale = tous les postes.','Swiss GAAP RPC 30',2);
q('Comptabilité','notion','Une participation avec influence notable, sans contrôle, relève en principe de…',['L’intégration globale','La mise en équivalence'],1,'La mise en équivalence suit la quote-part des capitaux propres de l’entreprise associée.','Influence : une ligne. Contrôle : tous les postes.','Swiss GAAP RPC 30',2);
q('Comptabilité','cas','Lunéa SA, atelier jurassien, vend une machine encaissée comptant : quel flux ?',['Exploitation','Investissement','Financement'],1,'La vente d’une immobilisation produit un flux d’investissement.','Machine = investissement.');
q('Comptabilité','cas','Brumelle Sàrl, à Fribourg, reçoit un nouvel emprunt bancaire : quel flux ?',['Exploitation','Investissement','Financement'],2,'Un nouvel emprunt modifie le financement de l’entreprise.','Banque qui prête = financement.');
q('Comptabilité','notion','Une marge sur coûts variables correspond à…',['Chiffre d’affaires moins coûts variables','Chiffre d’affaires moins coûts fixes'],0,'Elle contribue à couvrir les coûts fixes puis à dégager un bénéfice.','La marge paie ensuite les fixes.');
q('Comptabilité','notion','Une valeur actuelle nette positive signifie que le projet…',['Dépasse le rendement exigé au taux retenu','Ne présente aucun risque'],0,'Une VAN positive indique une création de valeur au taux d’actualisation choisi ; le risque subsiste.','VAN positive : valeur ajoutée, pas risque effacé.','',2);
q('Comptabilité','notion','Un contrôle interne qui sépare commande, paiement et comptabilisation applique…',['La séparation des fonctions','La consolidation'],0,'La séparation des fonctions limite les possibilités d’erreur et de fraude.','Trois tâches sensibles : plusieurs paires d’yeux.');
q('Comptabilité','notion','Le prix d’acquisition dépasse les actifs nets identifiables acquis. L’écart positif est…',['Un goodwill','Un badwill'],0,'Le goodwill est l’écart positif d’acquisition selon les règles de valorisation applicables.','GOOD : prix au-dessus des actifs nets.','Swiss GAAP RPC 30',2);
q('Comptabilité','notion','La dissolution d’une réserve latente a généralement quel effet sur le résultat ?',['Elle l’augmente','Elle le diminue'],0,'La dissolution augmente le résultat publié par rapport au résultat sans cette dissolution.','On libère la réserve : le résultat remonte.','',2);
q('Comptabilité','notion','Une clé de répartition sert principalement à attribuer des coûts…',['Indirects','Directs'],0,'Les coûts indirects nécessitent une répartition entre objets de coût.','Indirect : il faut une clé pour entrer.');
q('Fiscalité','notion','Une exportation de biens remplissant les conditions légales est en principe…',['Exclue du champ de l’impôt','Exonérée de l’impôt'],1,'L’exportation est exonérée, avec maintien du droit à déduction de l’impôt préalable selon les conditions légales.','EXportation : EXonération.','LTVA 23');
q('Fiscalité','notion','Une prestation exclue, sans option, ouvre-t-elle en principe le droit à la déduction de l’impôt préalable qui lui est affecté ?',['Oui','Non'],1,'L’impôt préalable affecté à une prestation exclue sans option n’est en principe pas déductible.','Exclu : la déduction reste dehors.','LTVA 29');
q('Fiscalité','notion','Soumettre volontairement une prestation exclue à la TVA, lorsque c’est autorisé, s’appelle…',['L’option','L’exonération'],0,'L’option permet l’imposition volontaire de certaines prestations exclues.','OPtion : OPter pour imposer.','LTVA 22');
q('Fiscalité','notion','Avec la méthode des taux de la dette fiscale nette, l’impôt préalable est…',['Déduit séparément facture par facture','Pris en compte forfaitairement dans la méthode'],1,'Le TDFN simplifie le décompte ; l’impôt préalable n’est pas déterminé séparément.','Nette : le forfait fait le ménage.');
q('Fiscalité','chiffre','Quel est le taux normal de TVA retenu dans cette banque ?',['8,1 %','7,7 %','2,6 %','3,8 %'],0,'Le taux normal en vigueur est de 8,1 %.','Normal : huit virgule un.','LTVA 25');
q('Fiscalité','chiffre','Quel est le taux réduit de TVA ?',['3,8 %','2,6 %','8,1 %','2,5 %'],1,'Le taux réduit est de 2,6 %.','Réduit : le plus petit des trois.','LTVA 25');
q('Fiscalité','chiffre','Quel taux spécial s’applique aux prestations d’hébergement ?',['2,6 %','8,1 %','3,8 %','5 %'],2,'Le taux spécial d’hébergement est de 3,8 %.','Une chambre : trois virgule huit.','LTVA 25');
q('Fiscalité','notion','Un avantage accordé à un actionnaire sans contre-prestation adéquate peut constituer…',['Une prestation appréciable en argent','Une charge automatiquement déductible'],0,'Une prestation appréciable en argent peut entraîner une reprise fiscale et des conséquences en impôt anticipé.','Actionnaire favorisé : fisc intéressé.','',2);
q('Salaires','notion','Le salaire servant de base à la prévoyance professionnelle après coordination est le…',['Salaire coordonné','Salaire déterminant AVS'],0,'La coordination adapte la base LPP à la couverture du premier pilier.','Coordonné = COordination LPP.','LPP 8');
q('Salaires','notion','Le seuil d’entrée LPP sert à déterminer…',['L’accès à l’assurance obligatoire selon les conditions légales','La somme toujours déduite du salaire AVS'],0,'Le seuil d’entrée est une condition d’assujettissement. La déduction de coordination a une autre fonction.','Seuil = porte. Déduction = ciseaux.','LPP 7');
q('Salaires','chiffre','Quel est le seuil annuel d’entrée LPP pour 2027 ?',['23 040 CHF','26 880 CHF','22 680 CHF','3 840 CHF'],0,'Le seuil d’entrée passe à 23 040 CHF en 2027.','23 040 ouvre la porte.','LPP 7');
q('Salaires','chiffre','Quelle est la déduction annuelle de coordination LPP en 2027 ?',['23 040 CHF','26 880 CHF','26 460 CHF','7 373 CHF'],1,'La déduction de coordination est de 26 880 CHF en 2027.','26 880 : les ciseaux de coordination.','LPP 8');
q('Salaires','chiffre','Quel taux d’intérêt minimal rémunère les avoirs LPP obligatoires en 2027 ?',['1,25 %','1,75 %','2 %','3 %'],2,'Le Conseil fédéral a fixé le taux minimal à 2 % dès janvier 2027.','Deux piliers ? Deux pour cent pour le deuxième.');
q('Salaires','chiffre','Pour une personne affiliée à une institution de prévoyance, quel plafond 3a pour 2027 ?',['7 258 CHF','7 373 CHF','36 864 CHF','26 880 CHF'],1,'Le plafond annuel avec deuxième pilier est de 7 373 CHF pour 2027.','Avec LPP : le petit plafond 3a.','OPP 3 7');
q('Salaires','notion','Les heures au-delà de la durée contractuelle, mais sous le maximum légal, sont en principe…',['Des heures supplémentaires','Du travail supplémentaire'],0,'Les heures supplémentaires dépassent la durée convenue ; le travail supplémentaire dépasse le maximum légal.','Contrat : heures. Loi : travail.','CO 321c');
q('Salaires','notion','Un congé dont le motif est abusif se distingue d’un congé donné pendant une période protégée : ce dernier est…',['Un congé en temps inopportun','Toujours un congé abusif'],0,'Le motif abusif et le moment interdit constituent deux mécanismes distincts.','Abusif : pourquoi ? Inopportun : quand ?','CO 336 / CO 336c',2);
q('Salaires','notion','Une indemnité journalière maladie et une allocation APG sont…',['Deux prestations de régimes distincts','Toujours la même assurance'],0,'L’IJ maladie couvre une incapacité selon le contrat ou le régime applicable. Les APG couvrent des situations légales spécifiques.','Maladie : IJ. Événements légaux APG : autre guichet.');
q('Salaires','cas','Orivelle SA, fleuriste à Sion, fait travailler une employée 10 heures par semaine : la couverture LAA inclut en principe…',['Les accidents professionnels seulement','Les accidents professionnels et non professionnels'],1,'Dès huit heures hebdomadaires chez le même employeur, la couverture inclut en principe les accidents non professionnels.','Huit heures : les loisirs entrent dans la couverture.','LAA / OLAA');

// Expanded conceptual bank: no multistep calculations.
const extraRows=[
['Comptabilité','Une charge comptabilisée sans sortie de trésorerie dans l’exercice est…','Un amortissement|Un remboursement d’emprunt',0,'L’amortissement répartit le coût d’un actif sur sa durée d’utilisation. Il réduit le résultat sans provoquer lui-même un paiement. Un remboursement d’emprunt, au contraire, diminue la trésorerie et la dette sans constituer une charge.','Résultat et argent ne suivent pas le même calendrier.'],
['Comptabilité','Une entreprise rembourse le principal d’un emprunt. Son résultat est…','Diminué du remboursement|Non affecté par le principal',1,'Le principal rembourse une dette : on diminue la banque et l’emprunt. Ce mouvement ne touche pas le compte de résultat. Les intérêts constituent, eux, une charge financière.','Principal : dette. Intérêts : charge.'],
['Comptabilité','Un client règle une facture déjà enregistrée. Ce paiement crée…','Un nouveau produit|Une entrée de liquidités sans nouveau produit',1,'Le produit a déjà été enregistré lors de la vente. Le règlement transforme une créance en trésorerie. Enregistrer à nouveau un produit compterait deux fois la même vente.','Encaisser une créance ne signifie pas vendre deux fois.'],
['Comptabilité','Une vente à crédit peut produire…','Un bénéfice sans encaissement immédiat|Un encaissement immédiat obligatoire',0,'Le produit est reconnu selon les règles de rattachement applicables, tandis que le client peut payer plus tard. Une entreprise rentable peut donc manquer de liquidités. Il faut distinguer résultat et capacité de paiement.','Bénéfice sur papier, trésorerie en banque.'],
['Comptabilité','Le paiement d’une dette fournisseur déjà comptabilisée entraîne…','Une nouvelle charge|Une diminution de la dette et de la banque',1,'La charge ou l’actif concerné a déjà été enregistré à réception de la facture. Lors du paiement, seule la dette fournisseur disparaît contre la trésorerie. Il n’y a pas une seconde charge.','Payer éteint la dette.'],
['Comptabilité','Dans un bilan, le total des actifs est égal…','Au total des capitaux étrangers seulement|Au total des capitaux étrangers et propres',1,'Les actifs montrent l’utilisation des ressources. Les capitaux étrangers et propres montrent leur origine. Ces deux lectures d’un même patrimoine doivent avoir le même total.','Emplois = ressources.'],
['Comptabilité','Le bénéfice conservé dans l’entreprise est une source…','D’autofinancement|D’endettement bancaire',0,'Une part du résultat non distribuée renforce les ressources propres de l’entreprise. Un emprunt provient d’un tiers et doit être remboursé. Conserver un bénéfice ne garantit toutefois pas que ce montant soit entièrement disponible en banque.','Bénéfice gardé : financement de l’intérieur.'],
['Comptabilité','Un apport en espèces des associés augmente directement…','Les produits des ventes|La trésorerie et les capitaux propres',1,'L’apport est une opération avec les propriétaires. Il finance l’entreprise mais ne rémunère pas une vente à un client. Il n’augmente donc pas le résultat de l’exploitation.','Apport du propriétaire : capital, pas chiffre d’affaires.'],
['Comptabilité','Une réserve ouverte se reconnaît parce qu’elle est…','Présentée dans les capitaux propres|Toujours cachée dans les stocks',0,'La réserve ouverte apparaît explicitement au bilan dans les capitaux propres. Une réserve latente n’apparaît pas sous son propre nom : elle résulte d’évaluations prudentes d’actifs ou de passifs.','Ouverte : visible. Latente : dans l’évaluation.'],
['Comptabilité','Une perte de valeur économique d’un actif et son amortissement planifié sont…','Deux notions distinctes|Toujours la même opération',0,'L’amortissement planifié répartit systématiquement le coût sur la durée d’utilisation. Une dépréciation répond à une perte de valeur spécifique. Une panne durable ou un marché qui s’effondre peut justifier une analyse de perte de valeur en plus du plan ordinaire.','Plan : usure prévue. Dépréciation : perte constatée.'],
['Comptabilité','La durée d’utilisation estimée d’une machine concerne principalement…','Son plan d’amortissement|Le délai de paiement des clients',0,'La durée d’utilisation sert à répartir le coût amortissable entre les exercices bénéficiaires de l’actif. Elle ne se confond ni avec la durée de financement ni avec le délai accordé aux clients.','Durée d’usage : durée de répartition.'],
['Comptabilité','Un bilan décrit une situation…','À une date donnée|Sur toute une période uniquement',0,'Le bilan est une photographie du patrimoine à une date précise. Le compte de résultat décrit les charges et produits d’une période. Il faut distinguer un stock à une date et un flux pendant une période.','Bilan : photo. Résultat : film.'],
['Comptabilité','Les charges et produits sont présentés dans…','Le compte de résultat|Le tableau des seules créances',0,'Le compte de résultat rapproche les produits et charges de l’exercice pour déterminer le bénéfice ou la perte. Le bilan présente les actifs, les dettes et les capitaux propres à la clôture.','Le résultat raconte l’exercice.'],
['Comptabilité','Une dette à rembourser à long terme se distingue d’une dette à court terme par…','Son échéance|La couleur du compte bancaire',0,'Le classement par échéance renseigne sur la pression de remboursement et la liquidité. Le montant seul ne suffit pas pour distinguer court et long terme. La lecture de l’échéancier complète celle du bilan.','Court ou long : regarde le calendrier.'],
['Comptabilité','Un stock destiné à la vente est en principe…','Une immobilisation d’exploitation|Un actif circulant',1,'Les stocks sont acquis ou fabriqués pour être vendus ou consommés dans le cycle d’exploitation. Une immobilisation est détenue durablement pour servir l’activité. Le même type de bien peut changer de catégorie selon son usage.','Revendre : stock. Utiliser durablement : immobilisation.'],
['Comptabilité','Chez un marchand de machines, une machine achetée pour être revendue est…','Un stock|Toujours une immobilisation',0,'Le critère déterminant est la destination économique du bien. Le commerçant revend cette machine dans son activité ordinaire. La machine utilisée dans son propre atelier serait au contraire une immobilisation.','Ce que tu en fais compte plus que son nom.'],
['Comptabilité','Le coût variable total augmente proportionnellement au volume. Son coût par unité reste…','Constant dans ce modèle|Croissant par définition',0,'Dans un modèle linéaire, chaque unité entraîne le même coût variable unitaire. Le total augmente avec le nombre d’unités. Il ne faut pas confondre coût total et coût unitaire.','Variable au total, stable par unité.'],
['Comptabilité','Si le coût fixe total reste constant et que la production augmente, le coût fixe par unité…','Diminue|Augmente nécessairement',0,'La même somme fixe est répartie sur davantage d’unités. C’est un effet de dilution, valable dans la plage de capacité considérée. Au-delà d’un palier, de nouveaux coûts fixes peuvent apparaître.','Même gâteau, plus de parts.'],
['Comptabilité','Un coût direct est nécessairement variable : cette affirmation est…','Juste|Fausse',1,'Direct ou indirect décrit l’attribution à un objet de coût. Fixe ou variable décrit la réaction au volume. Un équipement réservé à un produit peut engendrer un coût fixe directement attribuable à ce produit.','Attribution et comportement : deux axes.'],
['Comptabilité','Un centre de coûts permet principalement…','De regrouper des charges par lieu de responsabilité|De fixer automatiquement le prix du marché',0,'Le centre de coûts rassemble les coûts d’un service ou d’une responsabilité. On peut ensuite analyser ou répartir ces coûts vers les objets de coût. Il ne remplace pas l’étude commerciale des prix de vente.','Centre : où ? Objet : pour quoi ?'],
['Comptabilité','Un objet de coût répond principalement à la question…','Pour quel produit ou service ?|Sur quel compte bancaire ?',0,'L’objet de coût est ce dont on veut mesurer le coût : produit, service, mandat ou client. Un centre de coûts localise les charges. L’objet en explique la destination finale.','Objet : ce que tu veux chiffrer.'],
['Comptabilité','Au seuil de rentabilité, le résultat est…','Nul|Égal au chiffre d’affaires',0,'Le chiffre d’affaires couvre exactement les coûts de la période dans le modèle retenu. La marge sur coûts variables couvre les coûts fixes. Au-delà du seuil, les ventes supplémentaires contribuent au bénéfice.','Seuil : ni bénéfice ni perte.'],
['Comptabilité','Pour une commande supplémentaire dans une capacité disponible, un coût irrécupérable est…','Déjà engagé et non modifié par la décision|Toujours le coût décisif',0,'Le coût irrécupérable est passé et ne change pas selon le choix présent. La décision doit examiner les coûts et revenus futurs pertinents, ainsi que les limites de capacité et les effets commerciaux.','Le passé ne change pas avec ta décision.'],
['Comptabilité','Le coût d’opportunité désigne…','La valeur de la meilleure alternative abandonnée|Une facture nécessairement comptabilisée',0,'Choisir une option peut empêcher d’en réaliser une autre. Le rendement abandonné constitue un coût pertinent pour la décision, même sans pièce comptable ni paiement. Ce n’est pas automatiquement une charge en comptabilité générale.','Choisir, c’est renoncer à une alternative.'],
['Comptabilité','Un budget est…','Un plan chiffré pour une période future|Le résultat définitivement réalisé',0,'Le budget traduit des hypothèses et objectifs en valeurs attendues. Le réalisé constate ce qui s’est effectivement passé. L’écart sert ensuite à comprendre les différences et à adapter les décisions.','Budget : prévu. Réalisé : constaté.'],
['Comptabilité','Une hausse des créances clients non encore encaissées absorbe en principe…','De la trésorerie dans le cycle d’exploitation|Aucune ressource',0,'L’entreprise a livré et enregistré des ventes sans recevoir tout l’argent correspondant. Davantage de ressources restent immobilisées chez les clients. À conditions comparables, cela accroît le besoin de financement de l’exploitation.','Créance en hausse : argent encore chez le client.'],
['Comptabilité','Une augmentation des stocks peut améliorer le bénéfice tout en…','Consommant de la trésorerie|Créant automatiquement des liquidités',0,'Constituer un stock mobilise des ressources, même si le résultat ne suit pas immédiatement le paiement. Le bénéfice et la trésorerie doivent être analysés séparément. La variation du stock est donc importante pour les flux d’exploitation.','Stock rempli, banque parfois vidée.'],
['Comptabilité','L’achat au comptant d’une immobilisation relève du flux…','D’exploitation|D’investissement',1,'L’entreprise transforme de la trésorerie en actif durable. Le paiement appartient aux activités d’investissement. Les amortissements futurs affecteront le résultat mais ne répéteront pas ce paiement.','Actif durable : investissement.'],
['Comptabilité','Une augmentation de capital encaissée relève du flux…','De financement|D’investissement',0,'Les propriétaires apportent de nouvelles ressources financières. Ce flux concerne l’origine du financement. Il ne faut pas le confondre avec l’achat d’un actif financé grâce à cet apport.','Origine de l’argent : financement.'],
['Comptabilité','Le ratio de liquidité et la rentabilité mesurent…','Deux dimensions différentes|Exactement le même risque',0,'La liquidité concerne la capacité de faire face aux paiements. La rentabilité mesure un résultat rapporté aux ressources ou aux ventes. Une entreprise peut être rentable et manquer de trésorerie à court terme.','Rentable ne signifie pas liquide.'],
['Comptabilité','Le rendement des capitaux propres rapporte un résultat…','Aux capitaux propres|Au seul nombre de clients',0,'Ce ratio examine le rendement des ressources appartenant aux propriétaires. Il se distingue de la marge sur ventes et du rendement des capitaux totaux. Il faut conserver des définitions cohérentes du résultat et du capital utilisé.','ROE : rendement pour les propriétaires.'],
['Comptabilité','Un délai de récupération court garantit-il la meilleure rentabilité globale ?','Oui, toujours|Non',1,'Le délai de récupération mesure la vitesse de retour du capital engagé. Il peut ignorer des flux postérieurs au remboursement et, dans sa version simple, la valeur temps de l’argent. Une décision complète ne repose pas sur cet indicateur seul.','Vitesse de retour ne vaut pas rendement total.'],
['Comptabilité','L’actualisation sert à…','Ramener des flux futurs à une valeur présente|Additionner des montants sans tenir compte du temps',0,'Une somme disponible aujourd’hui n’est pas équivalente à la même somme reçue plus tard. L’actualisation applique un taux reflétant les exigences retenues pour comparer ces dates. Elle rend les flux temporellement comparables.','Actualiser : exprimer aujourd’hui.'],
['Comptabilité','Dans un groupe, une vente interne doit être éliminée pour éviter…','De présenter une opération interne comme une vente à un tiers|D’enregistrer toute vente externe',0,'Les comptes consolidés présentent le groupe comme une seule entité économique. Une vente entre deux sociétés du groupe ne constitue pas une vente à l’extérieur. L’élimination ne supprime pas la vente réellement réalisée à un client tiers.','Le groupe ne se vend pas à lui-même.'],
['Comptabilité','Les participations de tiers dans une filiale consolidée globalement représentent…','La part des capitaux propres qui n’appartient pas à la société mère|Un emprunt de la société mère',0,'L’intégration globale reprend les postes de la filiale en totalité. La part économique des autres propriétaires doit donc être distinguée. Elle ne se transforme pas en dette bancaire du groupe.','Tiers propriétaires, pas tiers prêteurs.'],
['Comptabilité','Une créance et une dette réciproques entre sociétés consolidées sont…','Éliminées à la consolidation|Additionnées comme une dette externe supplémentaire',0,'Les comptes individuels constatent correctement la relation entre les deux sociétés. Du point de vue du groupe pris comme une seule entité, il n’existe cependant pas de créance sur lui-même. Les soldes réciproques doivent être rapprochés puis éliminés.','Interne : à neutraliser au niveau du groupe.'],
['Comptabilité','Les comptes individuels et les comptes consolidés sont…','Deux niveaux de présentation distincts|Toujours un seul document identique',0,'Les comptes individuels décrivent une personne juridique. Les comptes consolidés décrivent un groupe économique. Une élimination de consolidation n’efface donc pas automatiquement l’écriture des comptes individuels.','Individuel : société. Consolidé : groupe.'],
['Comptabilité','Le contrôle interne offre…','Une maîtrise raisonnable des risques|Une garantie absolue contre toute fraude',0,'Les contrôles réduisent les risques mais ont des limites : erreur humaine, collusion ou contournement. Leur conception doit être adaptée aux enjeux. La présence d’une procédure ne suffit pas si elle n’est pas appliquée.','Contrôler réduit le risque, sans le rendre nul.'],
['Comptabilité','Un rapprochement bancaire sert à…','Expliquer les différences entre banque et comptabilité|Remplacer toutes les pièces justificatives',0,'On compare le solde comptable au relevé bancaire et on identifie les décalages ou erreurs. Les différences doivent être documentées et corrigées si nécessaire. Ce contrôle ne dispense pas de conserver les justificatifs des opérations.','Deux soldes, une explication pour chaque différence.'],
['Comptabilité','Une facture reçue avant la clôture mais relative à l’exercice suivant nécessite une analyse…','Du rattachement à la bonne période|De la seule date imprimée',0,'La date de la pièce n’est pas le seul critère économique. Il faut déterminer quand la prestation ou la consommation concerne l’entreprise. Une régularisation peut alors être nécessaire pour présenter le bon résultat de chaque exercice.','Bonne période avant belle date.'],
['Fiscalité','La TVA et l’impôt sur le bénéfice frappent…','Des bases fiscales différentes|Toujours exactement la même base',0,'La TVA porte sur des opérations de consommation selon ses règles propres. L’impôt sur le bénéfice concerne le résultat fiscal. Une entreprise déficitaire peut donc devoir de la TVA, tandis qu’une opération exclue de TVA peut entrer dans le résultat imposable.','TVA : opérations. Bénéfice : résultat.'],
['Fiscalité','Une charge comptabilisée est-elle toujours déductible fiscalement ?','Oui|Non',1,'Le résultat commercial sert de point de départ, mais le droit fiscal peut imposer des corrections. Une charge privée ou non justifiée par l’usage commercial peut être reprise. Le fait qu’une dépense soit payée ne suffit pas à établir sa déductibilité.','Comptabilisé ne veut pas dire admis.'],
['Fiscalité','Une reprise fiscale d’une charge non admise augmente en principe…','Le bénéfice imposable|Le chiffre d’affaires TVA automatiquement',0,'La reprise neutralise la déduction d’une charge dans le calcul fiscal. Elle augmente donc le bénéfice imposable par rapport au résultat comptable avant correction. Les conséquences de TVA doivent être examinées séparément.','Reprise : on rajoute pour le fisc.'],
['Fiscalité','La preuve de l’exportation est importante parce qu’elle…','Permet de justifier les conditions de l’exonération|Remplace toute facture d’achat',0,'Le traitement fiscal favorable doit être justifié selon les exigences applicables. Une vente annoncée comme étrangère ne suffit pas à elle seule. Il faut pouvoir documenter la réalité et les conditions de l’opération.','Traitement fiscal : garde les preuves.'],
['Fiscalité','L’impôt préalable est principalement…','La TVA grevant les acquisitions de l’entreprise|Le bénéfice avant impôts',0,'L’entreprise peut supporter de la TVA sur ses achats. Le droit à déduction dépend ensuite de l’affectation et des conditions légales. L’impôt préalable n’est ni un taux de marge ni un impôt sur le bénéfice.','Préalable : TVA des achats en amont.'],
['Fiscalité','Une acquisition utilisée à la fois pour des activités ouvrant et n’ouvrant pas droit à déduction demande…','Une analyse de double affectation|Une déduction intégrale automatique',0,'L’usage de l’acquisition détermine l’étendue du droit à déduction. La part affectée à une activité sans droit à déduction ne devient pas déductible parce qu’une autre part l’est. Il faut appliquer une répartition appropriée et justifiable.','Usage mixte : droit à répartir.'],
['Fiscalité','Une diminution ultérieure du droit à déduction se distingue…','D’une augmentation ultérieure de ce droit|Uniquement par la couleur de la facture',0,'Quand l’affectation change, il faut examiner si le droit à déduction devient plus faible ou plus élevé. La correction et le dégrèvement ultérieur vont dans des directions opposées. Leur application dépend des conditions légales et de la situation du bien.','Moins de droit : corriger. Plus de droit : dégrever.'],
['Fiscalité','Un impôt retenu à la source signifie qu’il est…','Prélevé par le débiteur de la prestation selon le régime applicable|Toujours versé librement par le bénéficiaire en fin d’année',0,'Le prélèvement intervient chez celui qui verse la prestation, qui assume ensuite les obligations de déclaration et de versement prévues. Cela ne signifie pas que tous les impôts à la source relèvent du même régime. Il faut identifier l’impôt concerné.','À la source : chez celui qui verse.'],
['Salaires','Le salaire brut et le salaire net diffèrent notamment par…','Les retenues supportées par le salarié|Les seuls produits de l’employeur',0,'Le brut constitue le montant avant les retenues applicables au salarié. Le net correspond au montant après ces déductions et les autres éléments du décompte. Les charges patronales ne sont pas simplement toutes soustraites au salarié.','Brut avant retenues, net après.'],
['Salaires','Une cotisation patronale représente…','Une charge de l’employeur|Toujours une retenue sur le salaire net du salarié',0,'La part patronale incombe à l’employeur. La part salariale est prélevée sur la rémunération selon les règles applicables. Mélanger les deux fausse à la fois le coût du personnel et le montant à verser au salarié.','Patronale : payée par le patron.'],
['Salaires','Le coût total du personnel est-il toujours égal au salaire net versé ?','Oui|Non',1,'Le coût comprend la rémunération et les charges supportées par l’employeur. Le salaire net ne représente que le versement après les retenues applicables. Le coût et le paiement au salarié répondent donc à deux questions différentes.','Coût employeur et net salarié : deux angles.'],
['Salaires','Un remboursement de frais professionnels effectifs et documentés se distingue…','D’une rémunération du travail|Seulement par le nom donné au paiement',0,'Les frais compensent une dépense engagée pour l’activité professionnelle. Le salaire rémunère le travail. La qualification dépend de la réalité et des justificatifs ; renommer une rémunération en frais ne change pas sa nature.','Frais : compenser une dépense. Salaire : rémunérer.'],
['Salaires','Un accident professionnel et un accident non professionnel se distinguent principalement…','Par leur rapport avec l’activité professionnelle|Par le seul montant de la facture médicale',0,'La qualification dépend des circonstances et des règles de couverture. Un accident n’est pas professionnel simplement parce qu’il survient un jour ouvrable. Il faut examiner l’activité au moment de l’événement et le régime applicable.','Professionnel : lien avec le travail.'],
['Salaires','L’assurance-accidents et l’assurance-maladie couvrent…','Des risques définis différemment|Toujours le même événement avec les mêmes règles',0,'Un accident et une maladie répondent à des définitions distinctes. La branche d’assurance compétente et les conditions de prestations peuvent donc changer. Il faut qualifier l’événement avant de choisir le régime.','D’abord l’événement, ensuite l’assurance.'],
['Salaires','Le salaire assuré LAA est-il automatiquement identique au salaire coordonné LPP ?','Oui|Non',1,'Chaque assurance définit sa propre base, ses limites et ses règles de calcul. La coordination LPP répond à une logique différente de celle du gain assuré en assurance-accidents. Un seul salaire brut peut donc conduire à plusieurs bases d’assurance.','Une paie, plusieurs bases.'],
['Salaires','Le seuil d’entrée et le salaire coordonné minimal sont…','Deux montants avec deux fonctions distinctes|Deux noms pour le même seuil',0,'Le seuil d’entrée aide à déterminer l’assujettissement obligatoire. Le salaire coordonné minimal fixe une base minimale assurée lorsque les conditions sont réunies. L’un ouvre l’accès ; l’autre concerne l’étendue de la base assurée.','Entrée : accès. Minimal coordonné : couverture.'],
['Salaires','Le temps d’essai concerne principalement…','Une phase initiale de la relation de travail|Un droit permanent de licencier sans aucune règle',0,'Le temps d’essai est une période initiale soumise à des règles particulières. Il ne suspend pas toute protection ni toute obligation de l’employeur. Il doit être distingué de la durée totale du contrat et des délais ordinaires de congé.','Essai : début de la relation.'],
['Salaires','Une résiliation immédiate se distingue d’un congé ordinaire parce qu’elle…','Met fin au contrat sans attendre un délai ordinaire si les conditions sont remplies|Doit toujours attendre la fin du mois suivant',0,'La résiliation immédiate répond à des exigences spécifiques, notamment l’existence de justes motifs selon le cas. Elle ne doit pas être confondue avec une simple volonté de raccourcir un délai. L’absence de conditions peut entraîner des conséquences financières.','Immédiate : exception à justifier.'],
['Salaires','Les vacances servent principalement…','Au repos du travailleur|À transformer systématiquement le repos en salaire supplémentaire',0,'Le droit aux vacances vise le repos effectif. Il ne se réduit pas à une prime versée chaque année. La prise de vacances, leur fixation et les situations de fin de contrat doivent être analysées selon leurs règles propres.','Vacances : du repos avant tout.'],
['Salaires','La surindemnisation vise une situation où…','Le cumul de prestations dépasse la limite de coordination applicable|Aucune assurance ne verse de prestation',0,'Plusieurs régimes peuvent intervenir pour un même événement. Les règles de coordination empêchent certains cumuls excessifs, selon la limite applicable et les prestations prises en compte. Cela ne signifie pas que tout cumul soit interdit.','Coordonner : éviter un excès, pas tout cumul.']
];
extraRows.forEach(([m,p,answers,c,e,memo])=>q(m,'notion',p,answers.split('|'),c,e,memo,'',2));
const details=[
['Une provision couvre une obligation probable dont le montant ou l’échéance reste incertain. Elle réduit le résultat au moment de sa constitution. Une réserve est une composante des capitaux propres, alimentée notamment par les bénéfices conservés ou les apports.','Exemple : un litige probable peut appeler une provision ; conserver une partie du bénéfice alimente une réserve.'],
['L’origine de la ressource détermine la famille de réserve. Un agio provient des actionnaires lors d’un apport, alors qu’une réserve issue du bénéfice provient d’un résultat réalisé puis conservé.','Exemple : une action émise au-dessus du nominal produit un agio ; un bénéfice mis de côté appartient à l’autre famille.'],
['Le rattachement veut que la charge soit supportée par l’exercice qui a consommé la prestation. Si le paiement intervient plus tard, on constate une dette de régularisation à la clôture.','Exemple : l’électricité de décembre non encore facturée concerne décembre, même si la facture arrive en janvier.'],
['Le paiement a déjà eu lieu, mais l’entreprise n’a pas encore consommé la prestation correspondant à la période suivante. La régularisation évite de charger trop tôt le résultat.','Exemple : le loyer de janvier payé en décembre est présenté comme une charge payée d’avance au bouclement de décembre.'],
['Les deux méthodes produisent la même valeur comptable nette si les montants sont identiques. La méthode indirecte conserve le coût historique dans le compte d’actif et cumule les amortissements dans un compte correcteur.','Exemple : un véhicule peut rester inscrit à son coût brut avec un amortissement cumulé séparé.'],
['Une réserve latente peut résulter d’un actif sous-évalué ou d’un passif surévalué dans le cadre admis. Elle n’apparaît pas dans une rubrique de réserve ouverte au bilan.','Exemple : un stock inscrit en dessous de sa valeur admissible peut contenir une réserve latente.'],
['Fixe ou variable décrit le comportement du coût quand le volume change. Cette distinction n’est valable que dans la plage d’activité retenue. Si un nouvel atelier devient nécessaire, le coût fixe peut changer de palier.','Exemple : le loyer ne double pas simplement parce que l’atelier fabrique deux fois plus d’unités dans sa capacité disponible.'],
['Direct ou indirect décrit la possibilité d’attribuer le coût à l’objet étudié. Un coût indirect nécessite une clé ; un coût direct possède une destination identifiable. Ce critère est indépendant du caractère fixe ou variable.','Exemple : la matière d’un meuble est directe ; le chauffage partagé entre plusieurs produits est indirect.'],
['Le contrôle permet de présenter la filiale dans les comptes consolidés du groupe. Les postes sont repris intégralement puis les opérations internes sont éliminées. Les droits des autres propriétaires ne sont pas oubliés.','Exemple : une filiale contrôlée à 80 % n’est pas reprise à 80 % poste par poste ; la part des tiers est présentée séparément.'],
['L’influence notable permet de participer aux décisions sans contrôler l’entreprise. La mise en équivalence suit la participation par une valeur synthétique, au lieu d’additionner chaque actif et dette.','Exemple : une entreprise associée ne devient pas une filiale intégrée globalement simplement parce qu’elle verse un dividende.'],
['La machine est un actif durable. L’encaissement provient de sa cession et appartient donc aux flux d’investissement. Le résultat sur vente et le prix encaissé ne sont pas nécessairement identiques.','Exemple : vendre une machine n’est pas une vente ordinaire de marchandises pour l’atelier qui l’utilisait.'],
['L’emprunt apporte de la trésorerie avec une obligation de remboursement. Il modifie la structure de financement et ne constitue pas un produit de vente.','Exemple : le versement du prêt augmente la banque et les dettes financières.'],
['On retranche les coûts variables du chiffre d’affaires pour obtenir la contribution disponible. Cette contribution doit encore couvrir les coûts fixes ; elle n’est donc pas automatiquement le bénéfice.','Exemple : une marge sur coûts variables positive peut coexister avec une perte si les coûts fixes sont trop élevés.'],
['La VAN compare les flux actualisés avec le capital investi selon les hypothèses retenues. Un résultat positif indique que le projet dépasse le rendement exigé au taux utilisé, sans supprimer l’incertitude sur les flux.','Exemple : une prévision trop optimiste peut rendre une VAN séduisante sans garantir le résultat futur.'],
['Séparer les tâches sensibles limite la possibilité pour une seule personne d’engager, de payer puis de masquer une opération. Le contrôle doit rester adapté à la taille de l’entreprise et être réellement appliqué.','Exemple : une personne valide le paiement préparé par une autre.'],
['Le goodwill compare le prix payé avec les actifs nets identifiables acquis selon le référentiel applicable. Il ne représente pas une trésorerie disponible et ne doit pas être confondu avec le bénéfice de l’année.','Exemple : payer davantage pour une clientèle, une organisation ou des synergies peut contribuer à un écart positif.'],
['Une réserve latente constituée auparavant a réduit le résultat publié ou la valeur nette affichée. Sa dissolution libère cet effet et peut augmenter le résultat sans amélioration équivalente de l’activité de la période.','Exemple : réduire une correction de valeur devenue excessive peut faire remonter le résultat.'],
['Une clé traduit une hypothèse de consommation ou de causalité pour répartir un coût commun. Une mauvaise clé peut modifier fortement le coût calculé de chaque produit sans changer le coût total.','Exemple : répartir un loyer partagé selon les surfaces utilisées peut être plus pertinent que selon le nombre de salariés.']
];
bank.slice(0,18).forEach((x,i)=>{x.detail=details[i][0];x.example=details[i][1]});
bank.slice(18,36).forEach(x=>{x.detail=x.e+' La distinction porte sur la fonction ou le traitement de la notion, et non sur une simple différence de vocabulaire. Pour décider, identifie la situation décrite et vérifie les conditions applicables.';x.example='Dans ce cas, la réponse à retenir est : '+x.a[x.c]+'. '+x.memo;});
bank.slice(36).forEach(x=>{x.detail=x.e;x.example=x.memo;});


const originalDetails=["Une exportation légalement exonérée n’est pas soumise à l’impôt sur le territoire suisse, mais conserve en principe le droit à la déduction de l’impôt préalable affecté à cette activité. Une prestation exclue sans option n’a pas ce même droit. Les conditions et preuves de l’exportation doivent être réunies.", "L’absence de TVA sur la prestation ne suffit pas à identifier le régime. Dans une activité exclue sans option, la TVA des achats affectés à cette activité n’est en principe pas déductible. L’entreprise supporte donc cette TVA comme un coût, sous réserve des règles applicables.", "L’option consiste à soumettre volontairement certaines prestations exclues à la TVA lorsque la loi le permet. Elle change le traitement de la prestation et peut ouvrir le droit à déduction correspondant. Ce mécanisme ne s’applique pas sans conditions à toute activité exclue.", "La méthode effective détermine l’impôt sur les prestations puis tient compte de l’impôt préalable déductible. Le TDFN utilise un forfait propre à la méthode pour simplifier le décompte. On ne doit donc pas retrancher une deuxième fois toutes les factures d’impôt préalable.", "Le taux normal concerne les prestations imposables qui ne relèvent pas d’un taux réduit ou spécial. Il se distingue du taux de 2,6 % et de celui de 3,8 %. Identifier le taux exige de qualifier la prestation, pas seulement de constater qu’une facture contient de la TVA.", "Le taux réduit n’est pas un rabais choisi par l’entreprise : il dépend de la catégorie légale du bien ou de la prestation. Il faut le distinguer du taux normal et du taux spécial d’hébergement. La qualification de l’opération vient avant l’application du pourcentage.", "Le taux spécial concerne les prestations d’hébergement selon les conditions légales. Il ne s’applique pas automatiquement à toute facture d’un hôtel : les autres prestations doivent être qualifiées. Il faut donc distinguer la nuitée d’une autre consommation facturée.", "Une prestation appréciable en argent peut apparaître lorsqu’une société accorde à un actionnaire un avantage sans contre-prestation adéquate. L’analyse compare notamment ce qui aurait été convenu avec un tiers indépendant. La comptabilisation de l’avantage ne suffit pas à le rendre fiscalement admis.", "Le salaire coordonné relève du deuxième pilier. La déduction de coordination sert à articuler cette prévoyance avec le premier pilier. Le salaire déterminant AVS et le salaire coordonné ne constituent donc pas deux noms pour une même base.", "Le seuil d’entrée répond à la question de l’assujettissement obligatoire selon les conditions légales. La déduction de coordination répond à une autre question : quelle part du salaire entre dans la base coordonnée ? Ne soustrais pas le seuil d’entrée à la place de cette déduction.", "Le seuil d’entrée indique un montant de référence pour l’accès à la prévoyance professionnelle obligatoire. Il ne s’agit ni du montant déduit pour coordonner, ni du salaire coordonné minimal. Les autres conditions d’affiliation restent à examiner.", "La déduction de coordination permet d’articuler le deuxième pilier avec la couverture du premier. Elle ne constitue pas le seuil d’accès à l’assurance. Le salaire coordonné reste soumis aux limites et conditions applicables.", "Le taux minimal annoncé concerne la rémunération des avoirs de vieillesse du régime obligatoire. Il ne doit pas être confondu avec un taux de conversion en rente ou avec un rendement garanti de tous les placements. Le champ concerné par le pourcentage est donc aussi important que le chiffre.", "Ce plafond concerne les personnes affiliées à une institution de prévoyance professionnelle. Le régime sans deuxième pilier suit une règle distincte, avec une proportion du revenu et un maximum légal. Il ne suffit pas de choisir le montant le plus élevé du tableau.", "Les heures supplémentaires dépassent la durée convenue au contrat, sans nécessairement dépasser le maximum légal. Le travail supplémentaire vise le dépassement du maximum prévu par la législation sur le travail. La compensation et les règles applicables peuvent donc être différentes.", "Le congé abusif se rattache notamment au motif de la résiliation. Le congé en temps inopportun concerne une période protégée lorsque les conditions légales sont réunies. Les conséquences ne se déduisent pas d’une impression générale d’injustice : il faut identifier le mécanisme exact.", "L’indemnité journalière maladie couvre une perte de gain liée à la maladie dans le cadre du régime applicable. Les allocations APG répondent à des situations définies légalement, comme certains congés ou services. La présence d’une incapacité ou d’une absence ne suffit pas à appeler toute prestation APG.", "La durée hebdomadaire chez un même employeur est déterminante pour la couverture des accidents non professionnels. À dix heures, le seuil de huit heures est franchi. Cela ne transforme pas un accident de loisir en accident professionnel : les deux catégories restent distinctes."];bank.slice(18,36).forEach((x,i)=>x.detail=originalDetails[i]);
const modes=[['duel','01','Duel','Deux notions. Un choix.'],['vf','02','Vrai / Faux','30 secondes sur l’honneur.'],['flash','03','Flashcards','Ancre tes connaissances.'],['intrus','04','Intrus','Repère le passager clandestin.'],['range','05','Bonne case','Chaque notion à sa place.'],['who','06','Qui suis-je ?','Moins d’indices, plus d’XP.'],['trap','07','Chasse au piège','Une erreur se cache ici.'],['boss','08','Boss de module','5 questions. Objectif 4/5.']];
function due(){return allItems().filter(q=>state.reviews[q.id]?.due<=today())}function level(){return levels.filter(l=>state.xp>=l[0]).at(-1)}function go(p){page=p;session=null;render()}function render(){let links=[['Accueil','01'],['Jeux','02'],['Révisions','03'],['Stats','04']];for(let id of ['nav','mobile'])$('#'+id).innerHTML=links.map(([n,i])=>`<button class="${page===n?'active':''}" onclick="go('${n}')"><b>${i}</b> ${n}${n==='Révisions'&&due().length?' · '+due().length:''}</button>`).join('');$('#level').textContent=level()[1]+' · '+state.xp+' XP';if(session){drawQuestion();return}if(page==='Accueil')home();if(page==='Jeux')gamesPage();if(page==='Révisions')reviewsPage();if(page==='Stats')statsPage()}
const cards=()=>`<div class="games">${modes.map(([id,i,n,s],j)=>`<button class="game" onclick="start('${id}')"><span class="ico" style="--c:${['#e7edda','#f9e3cb','#e5def2','#dfe9ed'][j%4]}">${i}</span><strong>${n} <span style="float:right"></span></strong><small>${s}</small></button>`).join('')}</div>`;
function home(){$('#view').innerHTML=`<div class="intro"><div><div class="eyebrow">TON RENDEZ-VOUS AVEC LE DÉCLIC</div><h1>Petites sessions.<br>Grandes notions.</h1><p>Le brevet se prépare. Ton cerveau aussi.</p></div><div class="seal">BA</div></div><section class="hero"><div><div class="eyebrow">LE MIX DU JOUR · 10 QUESTIONS</div><h2>À toi de jouer.</h2><p>Des pièges, des déclics et quelques XP.<br>${due().length?due().length+' notion(s) à revoir en priorité.':'Une notion comprise, un pas de gagné.'}</p><button class="primary" onclick="start('mix')">Lancer ma session <span></span></button></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orb"></div><div class="orb"></div><div class="star">BA</div><div class="smalltag">+10 XP par déclic</div></div></section><div class="metrics"><div class="metric"><span class="number">${state.xp} <small style="display:inline">XP</small></span><small>Expérience cumulée</small></div><div class="metric"><span class="number">${state.days} <span style="font-size:16px">jours</span></span><small>Jours de série</small></div><div class="metric"><span class="number">${due().length.toString().padStart(2,'0')}</span><small>Notions à revoir</small></div></div><div class="sectiontitle"><h2>Choisis ton terrain de jeu</h2><span>8 façons de progresser</span></div>${cards()}<div class="bottomcard"><div><div class="eyebrow">PROCHAIN PALIER</div><h3 style="margin:8px 0">${levels.find(l=>l[0]>state.xp)?.[1]||'Expert brevet'}</h3><p>${Math.max(0,(levels.find(l=>l[0]>state.xp)?.[0]||state.xp)-state.xp)} XP avant le prochain niveau. Chaque déclic compte.</p></div><span style="font-size:35px"></span></div>${footer()}`}
function footer(){return `<div class="legal">Progression enregistrée sur cet appareil${storageOK?'': ' · stockage indisponible'}. <button class="textbtn" style="font-size:11px" onclick="go('Stats');setTimeout(()=>document.getElementById('sources').scrollIntoView(),0)">Sources & sauvegarde </button></div>`}
function gamesPage(){$('#view').innerHTML=`<div class="intro"><div><div class="eyebrow">LE MENU DES DÉCLICS</div><h1>Change de jeu.<br>Garde le cap.</h1></div></div><div class="row"><p class="sub">Choisis un module pour ta session.</p><select id="module" class="filter"><option>Tous les modules</option><option>Comptabilité</option><option>Fiscalité</option><option>Salaires</option></select></div>${cards()}<div class="bottomcard"><div><strong>Le Mix du jour</strong><p>50 % comptabilité · 25 % fiscalité · 25 % salaires.<br>Les révisions dues passent en premier.</p></div><button class="primary" onclick="start('mix')">Jouer </button></div>`}
function reviewsPage(){let d=due(),all=Object.entries(state.reviews);$('#view').innerHTML=`<div class="intro"><div><div class="eyebrow">RÉPÉTITION ESPACÉE</div><h1>Le déclic<br>qui reste.</h1><p>Ratée : prochaine session. Réussie : J+3, J+7, J+21.</p></div></div><div class="card"><h2>${d.length?d.length+' notion(s) t’attendent':'À jour. Bien joué.'}</h2><p class="sub">${d.length?'Les erreurs ont droit à une deuxième chance. Ton cerveau aussi.':'Lance une session pour alimenter tes prochaines révisions.'}</p><button class="primary" onclick="start('flash')">${d.length?'Revoir mes notions':'Découvrir des cartes'} </button></div><h2>Ton carnet de notions</h2>${all.length?all.map(([id,r])=>{let q=allItems().find(x=>x.id===id);if(!q)return '';return `<div class="listitem"><span class="eyebrow">${q.m}</span><p>${q.p}</p><details><summary>Revoir l’explication</summary>${detailHTML(q)}</details><span class="badge">${r.due<=today()?'À revoir maintenant':'Révision : '+new Date(r.due+'T12:00:00').toLocaleDateString('fr-CH')}</span></div>`}).join(''):'<p class="sub">Ton carnet est vide. Première mission : faire un déclic.</p>'}`}
function statsPage(){let next=levels.find(l=>l[0]>state.xp),total=state.history.reduce((a,h)=>a+h.n,0),right=state.history.reduce((a,h)=>a+h.right,0);$('#view').innerHTML=`<div class="intro"><div><div class="eyebrow">TA PROGRESSION</div><h1>Chaque notion<br>fait son chemin.</h1></div></div><div class="statgrid"><div class="card"><div class="eyebrow">${level()[1]}</div><h2>${state.xp} XP</h2><div class="progress"><div style="width:${next?(state.xp-level()[0])/(next[0]-level()[0])*100:100}%"></div></div><p class="sub">${next?next[0]-state.xp+' XP avant '+next[1]:'Sommet atteint. Garde tes réflexes affûtés.'}</p></div><div class="card"><div class="eyebrow">DEPUIS LE DÉBUT</div><h2>${total?Math.round(right/total*100):0} % de réussite</h2><p class="sub">${total} questions · ${state.history.length} sessions<br>${state.days} jour(s) de série</p></div></div><div class="card"><div class="eyebrow">OBJECTIF MARS 2027</div><h2>12 paliers. Une progression qui se mérite.</h2><p class="sub">Dernier palier : 15 000 XP. À environ 120 XP par jour, il faut 125 jours de jeu depuis zéro : une courte session quotidienne jusqu’à la seconde moitié de mars si tu commences mi-novembre. C’est une estimation, pas un déblocage automatique par date. Tu peux jouer autant que tu veux et avancer plus vite.</p><div class="ladder">${levels.map(([xp,title],i)=>`<div class="listitem row ${state.xp>=xp?'reached':''}"><span><strong>${String(i+1).padStart(2,'0')}</strong> · ${title}</span><span>${xp.toLocaleString('fr-CH')} XP${state.xp>=xp?' · atteint':''}</span></div>`).join('')}</div></div><h2>Les terrains à explorer</h2>${['Comptabilité','Fiscalité','Salaires'].map(m=>`<div class="listitem row"><strong>${m}</strong><span class="sub">${state.modules[m]||0} questions travaillées ${state.badges.includes(m)?' · Boss battu':''}</span></div>`).join('')}<h2>Dernières sessions</h2>${state.history.slice(-5).reverse().map(h=>`<div class="listitem row"><span>${h.mode} · ${h.date}</span><strong>${h.right}/${h.n} · +${h.xp} XP</strong></div>`).join('')||'<p class="sub">L’aventure commence à la première question.</p>'}<div class="card" id="sources"><h2>Ton sac de révision</h2><p class="sub">Les données restent dans ce navigateur. Exporte une sauvegarde pour changer de téléphone.</p><button class="primary" onclick="exportData()">Exporter ma progression </button><p><label class="textbtn">Importer une sauvegarde <input aria-label="Importer une sauvegarde JSON" type="file" accept="application/json" onchange="importData(this)" style="display:block;margin-top:12px;max-width:100%"></label></p><h3>Références</h3><p class="sub">Banque : ${bank.length} questions, ${intruders.length} intrus et ${classifyItems.length} éléments de classement. Sélection sans répétition tant que des éléments inédits sont disponibles dans le jeu et le module. Vérification des chiffres intégrés : 15 novembre 2026. Les montants non vérifiés ne sont pas proposés. Une banque éditoriale ne remplace pas les exercices type examen.</p><p class="sub"><a href="${sources.tva}" target="_blank" rel="noopener">AFC · TVA</a><br><a href="${sources.lpp}" target="_blank" rel="noopener">OFAS · Chiffres LPP 2027</a><br><a href="${sources.interest}" target="_blank" rel="noopener">OFAS · Intérêt minimal 2027</a><br><a href="${sources.co}" target="_blank" rel="noopener">Fedlex · Code des obligations</a></p><h3>Sur iPhone</h3><p class="sub">Ouvre le lien dans Safari, puis Partager → Sur l’écran d’accueil.</p></div>`}
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function shuffledQuestion(q){let order=shuffle(q.a.map((_,i)=>i));return {...q,a:order.map(i=>q.a[i]),c:order.indexOf(q.c)}}
function seenKey(mode){return mode==='mix'?'mix':mode}
function markSeen(q){let key=seenKey(session.mode);state.seen[key]??={};state.serial++;state.seen[key][q.id]=state.serial;session.shown.add(q.id);save()}
function selectQuestions(pool,n,mode){let day=today();let seen=state.seen[seenKey(mode)]||{};let ranked=shuffle(pool).sort((a,b)=>{let da=state.reviews[a.id]?.due<=day&&state.reviews[a.id]?.last!==day&&!(seen[a.id]>0),db=state.reviews[b.id]?.due<=day&&state.reviews[b.id]?.last!==day&&!(seen[b.id]>0);if(da!==db)return da?-1:1;return (seen[a.id]||0)-(seen[b.id]||0)});return ranked.slice(0,n)}
const intruders=[];
const families=[
['Comptabilité','les capitaux propres',['Capital-actions','Réserve issue du capital','Réserve issue du bénéfice','Bénéfice reporté','Apports des associés'],['Provision pour litige','Emprunt bancaire','Dette fournisseur'],'Les capitaux propres représentent les droits résiduels des propriétaires. Une provision, un emprunt et une dette fournisseur sont des capitaux étrangers, même si leur échéance ou leur montant peut varier.'],
['Comptabilité','les flux d’investissement',['Achat d’une machine au comptant','Vente encaissée d’un véhicule utilisé','Achat au comptant d’un bâtiment d’exploitation','Cession encaissée d’une installation'],['Encaissement d’un emprunt','Encaissement d’une augmentation de capital','Remboursement du principal d’un emprunt'],'L’investissement concerne les actifs durables. Les apports de capitaux et les emprunts concernent le financement. Il faut regarder la nature de l’opération et non le seul sens de circulation de l’argent.'],
['Comptabilité','les coûts variables dans un modèle proportionnel',['Matière par unité produite','Emballage par unité vendue','Commission proportionnelle aux ventes','Sous-traitance facturée par pièce'],['Loyer fixe dans la capacité disponible','Prime annuelle fixe d’assurance','Abonnement annuel fixe'],'Le coût variable total réagit au volume. Le coût fixe total reste stable dans la plage considérée. Un coût fixe peut changer à un nouveau palier de capacité sans devenir proportionnel à chaque unité.'],
['Fiscalité','les taux de TVA en vigueur',['Taux normal : 8,1 %','Taux réduit : 2,6 %','Hébergement : 3,8 %'],['Ancien taux normal : 7,7 %','Ancien taux réduit : 2,5 %','Ancien taux d’hébergement : 3,7 %'],'Les trois taux retenus sont 8,1 %, 2,6 % et 3,8 %. Les anciens taux ne doivent pas être utilisés pour identifier les taux actuels de la banque de révision.'],
['Fiscalité','les opérations qui ouvrent en principe le droit à déduction selon leurs conditions',['Vente ordinaire imposable','Exportation de biens légalement exonérée','Prestation exclue valablement soumise à l’option'],['Prestation exclue sans option','Dépense exclusivement privée sans droit à déduction','Achat affecté exclusivement à une prestation exclue sans option'],'Le droit à déduction dépend de l’affectation et des conditions légales. Une prestation exclue sans option n’a pas le même traitement qu’une prestation exonérée. Une utilisation privée ne crée pas un droit professionnel à déduction.'],
['Salaires','le deuxième pilier',['Seuil d’entrée LPP','Déduction de coordination','Salaire coordonné','Avoir de vieillesse LPP','Institution de prévoyance professionnelle'],['Pilier 3a','Prévoyance individuelle libre 3b','Épargne individuelle liée'],'Le deuxième pilier est la prévoyance professionnelle. Le troisième pilier relève de la prévoyance individuelle. Les deux complètent la prévoyance étatique mais ont des bases et des règles distinctes.'],
['Salaires','les notions qui concernent la rémunération du travail',['Salaire brut','Salaire net','Part salariale des cotisations','Part patronale des cotisations'],['Remboursement documenté d’une avance de frais professionnels','Restitution d’une dépense professionnelle justifiée','Remboursement de frais effectifs justifiés'],'La rémunération rétribue le travail. Le remboursement de frais effectifs compense une dépense professionnelle. La réalité du paiement et les justificatifs comptent davantage que le nom donné au poste.']
];
families.forEach(([m,family,inside,outside,e],fi)=>outside.forEach((out,oi)=>intruders.push({id:`intrus-${fi}-${oi}`,m,t:'notion',p:`Quel élément ne fait pas partie de cette famille : ${family} ?`,a:[...inside.slice(oi%Math.max(1,inside.length-2),oi%Math.max(1,inside.length-2)+3),out],c:3,e,detail:e,example:`L’intrus est « ${out} ». Les trois autres éléments partagent le critère annoncé.`,memo:'Commence par définir le critère de la famille.',diff:1})));
const categorySets=[
['Comptabilité','Fixe','Variable',['Loyer constant dans la plage d’activité','Prime annuelle fixe d’assurance','Abonnement annuel fixe','Salaire fixe du responsable pour la capacité considérée','Location mensuelle fixe d’une machine'],['Matière première par unité','Emballage par produit vendu','Commission proportionnelle au chiffre d’affaires','Transport facturé par unité livrée','Sous-traitance facturée par pièce'],'La distinction décrit le comportement du coût total lorsque le volume change. Elle ne dit pas si le coût est direct ou indirect.'],
['Comptabilité','Direct','Indirect',['Bois identifié pour un meuble précis','Temps de travail suivi exclusivement sur un mandat','Pièce incorporée à un produit identifié','Sous-traitance propre à une commande','Emballage spécifique à une seule gamme'],['Loyer commun réparti entre plusieurs produits','Chauffage partagé entre plusieurs gammes','Administration commune répartie entre mandats','Entretien commun réparti entre ateliers','Électricité commune non mesurée par produit'],'Direct signifie attribuable à l’objet étudié sans clé de répartition. Indirect signifie qu’une répartition est nécessaire.'],
['Comptabilité','Exploitation','Financement',['Règlement reçu d’un client ordinaire','Paiement d’un fournisseur de marchandises','Paiement de salaires','Encaissement d’une vente ordinaire au comptant','Paiement du loyer d’exploitation'],['Encaissement d’un nouvel emprunt bancaire','Remboursement du principal d’un prêt','Apport en espèces des associés','Encaissement d’une augmentation de capital','Remboursement de capital aux propriétaires'],'L’exploitation concerne le cycle ordinaire de l’activité. Le financement concerne les ressources apportées ou rendues aux prêteurs et aux propriétaires.'],
['Comptabilité','Actif','Passif',['Solde positif du compte bancaire','Créance client','Stock de marchandises','Machine d’exploitation','Charge payée d’avance'],['Dette fournisseur','Emprunt bancaire','Provision pour litige','Produit encaissé d’avance à régulariser','Dette de salaire à payer'],'L’actif présente les ressources et emplois de l’entreprise. Le passif présente les ressources de financement et les obligations.'],
['Salaires','Deuxième pilier','Troisième pilier',['Seuil d’entrée LPP','Déduction de coordination','Salaire coordonné','Avoir de vieillesse professionnel','Institution de prévoyance professionnelle'],['Pilier 3a','Prévoyance individuelle liée','Prévoyance individuelle libre 3b','Compte individuel d’épargne 3a','Assurance individuelle du pilier 3b'],'Le deuxième pilier relève de la prévoyance professionnelle. Le troisième relève de l’initiative individuelle, liée ou libre.'],
['Salaires','Heures supplémentaires','Travail supplémentaire',['Dépassement de la durée contractuelle sous le maximum légal','Heures au-delà du contrat sans dépassement de la limite légale','Travail supplémentaire au contrat, dans le maximum légal'],['Dépassement de la durée maximale légale','Heures au-dessus du plafond légal de travail','Dépassement du maximum fixé par la LTr'],'Le contrat et la limite légale sont deux références distinctes. Les heures supplémentaires relèvent du dépassement contractuel ; le travail supplémentaire dépasse le maximum légal.'],
['Fiscalité','Exclu sans option','Exonéré',['Formation remplissant les conditions légales d’exclusion, sans option','Traitement médical légalement exclu, sans option','Prestation de santé remplissant les conditions d’exclusion, sans option'],['Exportation de biens remplissant les conditions d’exonération','Livraison de biens exportés avec conditions et preuves remplies','Vente de biens exportés légalement exonérée'],'Exclu sans option et exonéré ne se confondent pas. Les conséquences sur la déduction de l’impôt préalable sont différentes.']
];
const classifyItems=[];categorySets.forEach(([m,a,b,aa,bb,e],si)=>{aa.forEach((p,i)=>classifyItems.push({id:`class-${si}-a${i}`,m,p,a:[a,b],c:0,e,detail:e,example:`« ${p} » appartient à la catégorie « ${a} ».`,memo:`La catégorie à retenir est ${a}.`,set:si}));bb.forEach((p,i)=>classifyItems.push({id:`class-${si}-b${i}`,m,p,a:[a,b],c:1,e,detail:e,example:`« ${p} » appartient à la catégorie « ${b} ».`,memo:`La catégorie à retenir est ${b}.`,set:si}))});
const allItems=()=>[...bank,...intruders,...classifyItems];
function start(mode){let module=$('#module')?.value||'Tous les modules';if(mode==='boss'&&module==='Tous les modules'){page='Jeux';gamesPage();$('#view').insertAdjacentHTML('afterbegin','<div class="feedback">Choisis le module de ton boss, puis touche « Boss de module ».</div>');return}let pool=(mode==='intrus'?intruders:mode==='flash'?allItems():bank).filter(q=>module==='Tous les modules'||q.m===module);let n=mode==='boss'?5:10;let pick;if(mode==='range'){let eligible=classifyItems.filter(q=>module==='Tous les modules'||q.m===module);let selectedSet=selectQuestions(eligible,1,'range')[0].set;let first=selectQuestions(eligible.filter(q=>q.set===selectedSet),5,'range');let otherSets=eligible.filter(q=>q.set!==selectedSet);let secondSet=otherSets.length?selectQuestions(otherSets,1,'range')[0].set:selectedSet;let second=selectQuestions(eligible.filter(q=>q.set===secondSet&&!first.some(x=>x.id===q.id)),5,'range');pick=[first,second].filter(g=>g.length===5)}else{pick=selectQuestions(pool,n,mode);if(mode==='mix'&&module==='Tous les modules'){let dueNew=pick.filter(q=>state.reviews[q.id]?.due<=today()&&state.reviews[q.id]?.last!==today());if(!dueNew.length){let split=state.history.filter(h=>h.mode==='Mix').length%2===0?[5,3,2]:[5,2,3];pick=['Comptabilité','Fiscalité','Salaires'].flatMap((m,i)=>selectQuestions(pool.filter(q=>q.m===m),split[i],mode));pick=shuffle(pick)}}if(mode==='vf')pick=[pick.slice(0,5),pick.slice(5,10)].filter(g=>g.length===5);else pick=pick.map(shuffledQuestion)}session={mode,module,pool:pick,index:0,right:0,count:0,xp:0,streak:0,errors:0,difficulty:1,answered:false,hint:1,answers:{},started:today(),missed:[],shown:new Set(),roundSeen:false};render()}
function current(){let x=session.pool[session.index];return Array.isArray(x)?x[0]:x}
function detailHTML(q){return `<p><strong>Pourquoi ?</strong><br>${q.detail||q.e}</p><p><strong>Repère concret</strong><br>${q.example||q.memo}</p>${q.law?`<small>Référence : ${q.law||''}</small>`:''}`}
function drawQuestion(){let s=session,q=current(),mode=modes.find(m=>m[0]===s.mode)?.[2]||'Mix du jour';if(!s.roundSeen){let qs=Array.isArray(s.pool[s.index])?s.pool[s.index]:[q];qs.forEach(markSeen);s.roundSeen=true;s.hint=1;s.truths=qs.map(()=>Math.random()<.5)}$('#view').innerHTML=`<div class="row" style="margin-top:25px"><span class="eyebrow">${mode} · ${q.m}</span><button class="textbtn" onclick="finish(true)">Terminer</button></div><div class="progress"><div style="width:${s.index/s.pool.length*100}%"></div></div><div class="row"><span class="sub">${s.mode==='vf'||s.mode==='range'?'Manche':'Question'} ${s.index+1} / ${s.pool.length}</span><span class="pill">${s.xp} XP · ${s.streak} de suite</span></div><div class="card" id="questioncard"><div class="eyebrow">${s.difficulty>1?'NIVEAU RELEVÉ · ':''}${s.mode==='boss'?'OBJECTIF 4 / 5':s.mode==='vf'?'30 SECONDES ! · SUR L’HONNEUR':'À TOI DE JOUER'}</div><div id="questionbody"></div><div id="feedback" aria-live="polite"></div></div>`;let b=$('#questionbody');if(s.mode==='vf'){s.group=s.pool[s.index].map((x,i)=>({...x,truth:s.truths[i],statement:x.p.replace(/…|\?$/g,'')+' → '+x.a[s.truths[i]?x.c:(x.c+1)%x.a.length]}));b.innerHTML='<h2>Vrai ou faux ?</h2>'+s.group.map((x,i)=>`<div class="vfrow"><span>${i+1}. ${x.statement}</span><div style="display:flex;gap:4px"><button class="toggle" id="v${i}" onclick="selectVF(${i},true)">V</button><button class="toggle" id="f${i}" onclick="selectVF(${i},false)">F</button></div></div>`).join('')+'<p class="sub">Choisis les cinq réponses, puis valide.</p><button class="primary" onclick="gradeVF()">Valider les cinq</button>';return}if(s.mode==='range'){s.group=s.pool[s.index];b.innerHTML='<h2>Range dans la bonne case.</h2>'+s.group.map((x,i)=>`<div class="listitem"><p>${x.p}</p><select aria-label="Catégorie ${i+1}" id="r${i}" style="width:100%"><option value="">Choisir…</option>${x.a.map((a,j)=>`<option value="${j}">${a}</option>`).join('')}</select></div>`).join('')+'<button class="primary" style="margin-top:20px" onclick="gradeRange()">Valider le classement</button>';return}if(s.mode==='flash'){b.innerHTML=`<h2 class="question">${q.p}</h2><button class="primary" style="margin-top:20px" onclick="revealFlash()">Voir la réponse</button>`;return}if(s.mode==='who'){b.innerHTML=`<h2 class="question">Qui suis-je ?</h2><p class="sub">Le contexte est donné dès le départ. Les indices suivants t’aident à affiner ta réponse.</p><div class="feedback"><strong>Contexte</strong><p>${q.p}</p></div><div id="hints"><p>Indice 1 · ${firstHint(q)}</p></div><button class="textbtn" id="hintbtn" onclick="hint()">Un indice de plus : 20 XP au lieu de 30</button>${choiceHTML(q)}`;return}if(s.mode==='trap'){s.trapWrong=(q.c+1)%q.a.length;b.innerHTML=`<h2 class="question">Repère et remplace l’erreur.</h2><p>${q.p.replace(/…|\?$/g,'')} → <strong>${q.a[s.trapWrong]}</strong></p><p class="sub">Quelle réponse corrige cette affirmation ?</p>${choiceHTML(q)}`;return}b.innerHTML=`<h2 class="question">${q.p}</h2>${choiceHTML(q)}`}
function firstHint(q){if(q.m==='Comptabilité')return q.t==='cas'?'Identifie la nature économique de l’opération, puis sa catégorie.':'Distingue l’origine, la destination ou le comportement de la notion décrite.';if(q.m==='Fiscalité')return q.t==='chiffre'?'Identifie le taux ou le seuil précis demandé ; les autres montants ne remplissent pas la même fonction.':'Cherche le traitement fiscal de l’opération et ses conséquences.';return q.t==='chiffre'?'Le montant demandé remplit une fonction précise dans ce régime de prévoyance.':'Identifie le régime ou la règle qui correspond à cette situation.'}
function hint(){if(!session||session.answered||session.hint>=3)return;let s=session,q=current();s.hint++;$('#hints').insertAdjacentHTML('beforeend',`<p>Indice ${s.hint} · ${s.hint===2?q.memo:(q.detail||q.e)}</p>`);$('#hintbtn').textContent='Dernier indice : 10 XP';if(s.hint===3)$('#hintbtn').hidden=true}
function choiceHTML(q){return `<div class="choices">${q.a.map((a,i)=>`<button class="choice" id="a${i}" onclick="answer(${i})"><b>${'ABCD'[i]}</b>${a}</button>`).join('')}</div>`}
function selectVF(i,v){if(session.answered)return;session.answers[i]=v;$('#v'+i).classList.toggle('selected',v);$('#f'+i).classList.toggle('selected',!v)}
function record(q,ok,points){state.xp+=points;session.xp+=points;session.count++;state.modules[q.m]=(state.modules[q.m]||0)+1;let r=state.reviews[q.id]||{step:0};if(!ok){r.step=0;r.due=today();session.missed.push(q)}else{r.due=addDays([3,7,21][Math.min(r.step,2)]);r.step=Math.min(3,r.step+1)}r.last=today();state.reviews[q.id]=r;save()}
function score(ok,q){let s=session;if(ok){s.streak++;s.errors=0;if(s.streak>=3)s.difficulty=2;s.right++}else{s.streak=0;s.errors++;if(s.errors>=2)s.difficulty=1}let points=ok?((s.mode==='who'?[30,20,10][s.hint-1]:10)+(s.streak>=3?5:0)):0;record(q,ok,points);return points}
function answer(i){if(!session||session.answered)return;let q=current(),ok=i===q.c;session.answered=true;let points=score(ok,q);document.querySelectorAll('.choice').forEach(b=>b.disabled=true);$('#a'+q.c)?.classList.add('correct');if(!ok)$('#a'+i)?.classList.add('wrong');feedback(ok,points,q)}
function feedback(ok,points,q,extra=''){$('#feedback').innerHTML=`<div class="feedback"><strong>${ok?'Juste. +'+points+' XP':'Pas encore. Reprenons la distinction.'}</strong>${q.a?`<p>Réponse : <strong>${q.a[q.c]}</strong></p>`:''}${extra||detailHTML(q)}${!ok&&q.memo?'<p><strong>À retenir</strong><br>'+q.memo+'</p>':''}</div><button class="primary" onclick="next()">${session.index+1===session.pool.length?'Voir mon bilan':'Question suivante'}</button>`}
function revealFlash(){let q=current();$('#questionbody').innerHTML=`<h2 class="question">${q.p}</h2><div class="feedback"><strong>${q.a[q.c]}</strong>${detailHTML(q)}</div><p class="sub">L’avais-tu retrouvé avant de voir la réponse ?</p><div class="row"><button class="choice" onclick="flashAnswer(false)">À revoir</button><button class="primary" onclick="flashAnswer(true)">Je savais</button></div>`}
function flashAnswer(ok){if(session.answered)return;session.answered=true;let q=current(),points=score(ok,q);feedback(ok,points,q);$('#questionbody').querySelectorAll('button').forEach(b=>b.disabled=true)}
function gradeVF(){if(session.answered)return;if(Object.keys(session.answers).length<5){alert('Choisis V ou F pour les cinq affirmations.');return}gradeGroup(session.group.map((q,i)=>session.answers[i]===q.truth))}
function gradeRange(){if(session.answered)return;let a=session.group.map((q,i)=>$('#r'+i).value);if(a.includes('')){alert('Choisis une case pour chaque élément.');return}gradeGroup(session.group.map((q,i)=>+a[i]===q.c))}
function gradeGroup(results){session.answered=true;let pts=0;session.group.forEach((q,i)=>{pts+=score(results[i],q)});let count=results.filter(Boolean).length;$('#questionbody').querySelectorAll('button,select').forEach(b=>b.disabled=true);feedback(count===5,pts,{memo:'Lis le raisonnement de chaque correction.'},`<p>${count}/5 réponses justes · +${pts} XP</p>`+session.group.map((q,i)=>`<details ${results[i]?'':'open'}><summary>${i+1}. ${results[i]?'Juste':'À revoir'} — ${q.a[q.c]}</summary>${detailHTML(q)}</details>`).join(''))}
function next(){if(!session?.answered)return;let s=session;s.index++;s.answered=false;s.roundSeen=false;s.answers={};if(s.index>=s.pool.length){finish();return}if(!['vf','range'].includes(s.mode)){let remaining=s.pool.slice(s.index),wanted=remaining.findIndex(q=>q.diff===s.difficulty);if(wanted>0){let i=s.index+wanted;[s.pool[s.index],s.pool[i]]=[s.pool[i],s.pool[s.index]]}}render()}
function finish(early=false){if(!session)return;let s=session,n=s.count;if(!n){go('Accueil');return}let before=state.last;if(before!==today()){state.days=before===addDays(-1)?state.days+1:1;state.last=today()}let won=s.mode==='boss'&&n===5&&s.right>=4;if(won&&!state.badges.includes(s.module))state.badges.push(s.module);let name=modes.find(m=>m[0]===s.mode)?.[2]||'Mix';state.history.push({mode:name,date:today(),n,right:s.right,xp:s.xp});save();session=null;$('#level').textContent=level()[1]+' · '+state.xp+' XP';let dates=Object.values(state.reviews).map(r=>r.due).sort(),nextDate=dates[0];let first=Array.isArray(s.pool[0])?s.pool[0][0]:s.pool[0],retain=s.missed[0]||first;$('#view').innerHTML=`<div class="card summary"><div class="eyebrow">${won?'BOSS BATTU · BADGE DÉBLOQUÉ':early?'SESSION TERMINÉE':'MISSION ACCOMPLIE'}</div><div class="number">${s.right}<span style="font-size:25px;color:var(--muted)"> / ${n}</span></div><h2>${s.right/n>=.8?'Les notions prennent place.':'Chaque erreur prépare un déclic.'}</h2><span class="badge">+${s.xp} XP</span><span class="badge">Palier ${levels.indexOf(level())+1}/12 · ${level()[1]}</span><span class="badge">${state.days} jour(s) de série</span><div class="feedback" style="text-align:left"><div class="eyebrow">LA NOTION À RETENIR</div><p><strong>${retain.p}</strong></p>${detailHTML(retain)}</div><p class="sub">Prochaine révision : ${!nextDate?'après tes prochaines réponses':nextDate<=today()?'disponible dans Révisions':new Date(nextDate+'T12:00:00').toLocaleDateString('fr-CH')}.</p>${s.mode==='boss'&&!won?'<p class="sub">Le boss demande 4/5. Tu peux le rejouer avec une nouvelle sélection.</p>':''}<button class="primary" onclick="start('${s.mode==='boss'?'mix':s.mode}')">Nouvelle partie</button><button class="textbtn" onclick="go('Accueil')">Accueil</button><p class="sub">Questions nouvelles en priorité. Après épuisement de la banque, les plus anciennes reviennent dans un ordre remélangé.</p></div>`}

function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}));a.download='brevet-arcade-progression.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function importData(input){let f=input.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result);if(x.version!==1||!Number.isFinite(x.xp)||x.xp<0||!Array.isArray(x.history)||!Array.isArray(x.badges)||typeof x.reviews!=='object')throw Error();if(!confirm('Remplacer la progression de cet appareil par cette sauvegarde ?'))return;state={xp:x.xp,days:Number.isFinite(x.days)?Math.max(0,x.days):0,last:/^\d{4}-\d{2}-\d{2}$/.test(x.last)?x.last:'',reviews:Object.fromEntries(Object.entries(x.reviews).filter(([id,r])=>allItems().some(q=>q.id===id)&&r&&/^\d{4}-\d{2}-\d{2}$/.test(r.due)&&Number.isInteger(r.step)&&r.step>=0&&r.step<=3)),modules:Object.fromEntries(['Comptabilité','Fiscalité','Salaires'].map(m=>[m,Number.isFinite(x.modules?.[m])?Math.max(0,x.modules[m]):0])),badges:x.badges.filter(m=>['Comptabilité','Fiscalité','Salaires'].includes(m)),seen:{},serial:state.serial||0,history:x.history.filter(h=>['Mix',...modes.map(m=>m[2])].includes(h.mode)&&/^\d{4}-\d{2}-\d{2}$/.test(h.date)&&[h.n,h.right,h.xp].every(v=>Number.isFinite(v)&&v>=0))};save();render()}catch(e){alert('Sauvegarde invalide. Choisis un export Brevet Arcade.')}};reader.readAsText(f)}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
